// I01–I03 (focused completion §3): the experiment INPUT BUNDLE — one immutable, versioned stream with a total order (receipt
// clock + capture sequence) written by the real composition beside the raw feed rows; closed validators at generation, reopen
// and the evaluation APIs; legacy raw-only recordings stay readable and are LIMITED by named missing capabilities; bounds are
// explicit failures, never silent truncation.
import test from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import { mkdtempSync, rmSync, writeFileSync, readFileSync, readdirSync, unlinkSync, mkdirSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { createHash } from 'node:crypto';

const TEST_DATA = mkdtempSync(path.join(tmpdir(), 'cobra-judge-bundle-')); process.env.COBRA_DATA_DIR = TEST_DATA;
const REC = await import('../judge/recorder.js'); const { createFeedRecorder, readRecording, verifyRecording, RECORDER_DEFAULTS, RECORDING_VERSION, MANIFEST_VERSION } = REC;
const B = await import('../judge/experiment-bundle.js'); const { readBundle, verifyBundle, replayCapabilities, recordError, createBundleStores, bundleBinding, BUNDLE_VERSION, TIE_ORDER_VERSION, CAPABILITY_REQUIREMENTS, BUNDLE_LIMITS } = B;
const { composeJudge } = await import('../judge/composition.js'); const { createMemoryJournal } = await import('../execution/journal.js'); const { runCli } = await import('../bin/judge.js');
const { KRAKEN_OHLC_URL } = await import('../judge/history.js'); const { fakeReplayClock } = await import('../judge/replay-clock.js'); const { consumeCase } = await import('../judge/intake.js');
const { fakeClock, SPEC, T0 } = await import('./helpers/judge.js'); const { instrumentSpec, digestOf } = await import('../execution/contract.js'); const { crc32 } = await import('../lib/crc32.js');
const { catalystPacket, analysisFor, verifiedCase } = await import('./helpers/case-fixture.js');
const PAPER_POLICY = path.resolve('judge/samples/policy.paper-reference.json');
const pclockOf = (clock) => ({ now: clock.now, monotonic: clock.monotonic, observeWall: () => null, status: () => ({ trusted: true, kind: 'TEST' }), expired: (t) => clock.now() > t });
const fmt = (v, d) => v.toFixed(d).replace('.', '').replace(/^0+/, ''); const crcFor = (asks, bids) => crc32([...asks.slice(0, 10), ...bids.slice(0, 10)].map(([p, q]) => fmt(p, 1) + fmt(q, 8)).join(''));
const bookMsg = (asks, bids, ts, type = 'update') => JSON.stringify({ channel: 'book', type, data: [{ symbol: 'XBT/USD', asks: asks.map(([price, qty]) => ({ price, qty })), bids: bids.map(([price, qty]) => ({ price, qty })), checksum: crcFor(asks, bids), timestamp: new Date(ts).toISOString() }] });
const tradeMsg = (price, ts, id) => JSON.stringify({ channel: 'trade', type: 'update', data: [{ symbol: 'XBT/USD', side: 'buy', price, qty: 0.05, ord_type: 'market', trade_id: id, timestamp: new Date(ts).toISOString() }] });
const HANDSHAKE = [JSON.stringify({ channel: 'instrument', type: 'snapshot', data: { pairs: [{ symbol: 'XBT/USD', price_precision: 1, qty_precision: 8 }] } }), JSON.stringify({ method: 'subscribe', success: true, result: { channel: 'trade', symbol: 'XBT/USD' } })];
const specFor = (coin) => instrumentSpec({ venue: 'kraken', pairKey: `${coin}USD`, altname: `${coin}USD`, wsname: `${coin}/USD`, base: coin, quote: 'ZUSD', canonicalCoin: coin, status: 'online', priceIncrement: '0.01', qtyIncrement: '0.00000001', orderMin: '0.01', costMin: '0.5', priceDecimals: 2, qtyDecimals: 8, observedTs: T0, source: 'FIXTURE' });
// a scripted public OHLC endpoint: 70 closed one-minute bars ending before the receipt, the provider's `last` = the latest committed bar
const ohlcTransport = (clock) => { const calls = []; const fn = async (url) => { const u = new URL(url); calls.push(u.pathname); if (!url.startsWith(KRAKEN_OHLC_URL)) return { status: 404, ok: false, text: async () => 'not found' }; const end = Math.floor(clock.now() / 60_000) * 60_000; const rows = []; for (let k = 70; k >= 1; k -= 1) { const s = (end - k * 60_000) / 1000; rows.push([s, '100000.0', '100010.0', '99990.0', '100005.0', '100002.0', '1.5', 12]); } return { status: 200, ok: true, text: async () => JSON.stringify({ error: [], result: { [u.searchParams.get('pair')]: rows, last: rows[rows.length - 1][0] } }) }; }; fn.calls = calls; return fn; };
const rows = (dir) => [...readRecording(dir)]; const kinds = (dir) => { const c = {}; for (const r of readBundle(dir)) c[r.kind] = (c[r.kind] ?? 0) + 1; return c; };
test.after(() => rmSync(TEST_DATA, { recursive: true, force: true }));

// the real composition records an experiment bundle: OBSERVE mode, a scripted feed, a scripted OHLC transport, a verified case fixture and a control change
async function recordBundle(dir, { coin, fx, analysis, controlFlip = true, extraNominations = [] } = {}) {
  const clock = fakeClock(fx.packet.asOfTs + 120_000); const verified = verifiedCase({ packet: fx.packet, analysis, coin, caseId: 'case-i01', finishedTs: fx.packet.asOfTs + 1000, verifiedTs: fx.packet.asOfTs + 2000 });
  const caseSource = { refresh: async () => {}, consumed: (c, { decisionTs }) => { if (c !== coin) return null; const r = consumeCase(verified, { canonicalCoin: coin, decisionTs }); return r.ok ? { ...r, dir: 'case-i01' } : null; }, verified: (d) => (d === 'case-i01' ? verified : null), status: () => ({ casesDir: 'fixture', known: 1, verified: 1 }) };
  let controls = { kill: false, cage: false, vetoes: [] }; const spec = instrumentSpec({ ...SPEC, wsname: `${coin}/USD`, pairKey: `${coin}USD`, altname: `${coin}USD`, canonicalCoin: coin, base: coin, specDigest: undefined });
  const transport = ohlcTransport(clock); const noms = [{ symbol: 'XBT/USD', assetId: 'BTC', nominationKnownAtTs: clock.now() - 5000 }, { symbol: `${coin}/USD`, assetId: coin, nominationKnownAtTs: clock.now() - 4000 }, ...extraNominations];
  const run = await composeJudge({ policyFile: PAPER_POLICY, mode: 'OBSERVE', accountId: 'bundle-rec', journal: createMemoryJournal(), clock: pclockOf(clock), transport, specs: [SPEC, spec], caseSource, controlsSource: () => controls, nominations: () => noms, recordDir: dir, writeProjection: false, codeDigest: 'c'.repeat(64), log: () => {}, experimentId: 'exp-i01' });
  const feed = run.tapeFeed; feed.onConnect(clock.now()); for (const h of HANDSHAKE) feed.ingest(h, clock.now()); feed.ingest(bookMsg([[100010.0, 5]], [[99990.0, 5]], clock.now(), 'snapshot'), clock.now());
  run.admitNominations(); await run.tick(); await new Promise((r) => setImmediate(r)); await run.tick();
  for (let i = 0; i < 6; i += 1) { clock.advance(1000); feed.ingest(bookMsg([[100010.0, 5 - i * 0.5]], [[99990.0, 5]], clock.now()), clock.now()); feed.ingest(tradeMsg(100000 + i, clock.now(), i + 1), clock.now()); if (i === 2 && controlFlip) controls = { kill: false, cage: true, vetoes: ['pred-1'] }; await run.tick(); }
  feed.onDisconnect(clock.now()); clock.advance(500); feed.onConnect(clock.now()); feed.ingest(bookMsg([[100010.0, 4]], [[99990.0, 5]], clock.now(), 'snapshot'), clock.now()); await run.tick();
  const stopped = await run.stop(); return { run, clock, stopped, verified, transport, spec };
}

test('I01. round trip through the REAL recorder and composition: feed bytes, nominations, instruments, fee, history retrievals, the consumed case (verifier output + digest) and control changes are ONE sealed stream in capture order; verifyBundle proves seal + order + every typed record; the bundle stores rebuild the runtime sources known-at gated; a cold CLI replay of the same bundle still runs; a missing middle segment, a reordered / duplicated sequence, future evidence, a wrong digest and an unknown version REFUSE', async () => {
  const fx = catalystPacket(); assert.equal(fx.valid, true); const coin = fx.coin; const analysis = analysisFor(fx.claim.claimId, 'UPWARD_PRESSURE', fx.packet); const dir = path.join(TEST_DATA, 'bundle-i01');
  const { stopped, verified, transport } = await recordBundle(dir, { coin, fx, analysis }); assert.ok(stopped.lifecycle.includes('WRITER_RELEASED'));
  const m = JSON.parse(readFileSync(path.join(dir, 'manifest.json'), 'utf8')); assert.equal(m.state, 'COMPLETE'); assert.equal(m.bundleVersion, BUNDLE_VERSION); assert.equal(m.tieOrderVersion, TIE_ORDER_VERSION); assert.equal(m.manifestVersion, MANIFEST_VERSION, 'the legacy manifest version is unchanged: old readers still open it');
  assert.deepEqual(m.binding, bundleBinding({ experimentId: 'exp-i01', policyDigest: m.binding.policyDigest, codeDigest: 'c'.repeat(64), strategyVersion: m.binding.strategyVersion, sourcePrefix: 'journal:bundle-rec', seed: m.binding.seed })); assert.match(m.binding.policyDigest, /^[0-9a-f]{64}$/); assert.ok(m.binding.strategyVersion);
  const c = kinds(dir); assert.ok(c.FEED >= 14, JSON.stringify(c)); assert.equal(c.CONNECT, 2); assert.equal(c.DISCONNECT, 1); assert.equal(c.NOMINATION, 2, 'each nomination once'); assert.equal(c.INSTRUMENT, 2); assert.equal(c.FEE, 1); assert.ok(c.HISTORY >= 1, 'the OHLC retrieval is captured'); assert.equal(c.CASE, 1, 'the consumed case once'); assert.equal(c.CONTROL, 2, 'the initial controls and the change'); assert.deepEqual(m.capabilities, { ...Object.fromEntries(B.RECORD_KINDS.map((k) => [k, 0])), ...c }, 'the manifest counts are the stream counts');
  assert.ok(transport.calls.includes('/0/public/OHLC')); const all = [...readBundle(dir)]; assert.deepEqual(all.map((r) => r.seq), all.map((_, i) => i + 1), 'one capture sequence, gapless'); assert.equal(m.lastSeq, all.length); assert.equal(m.records, all.length); assert.equal(m.messages, c.FEED + c.CONNECT + c.DISCONNECT, 'messages keeps the legacy meaning (feed rows)');
  for (let i = 1; i < all.length; i += 1) assert.ok(all[i].receiptTs >= all[i - 1].receiptTs, 'receipt clocks never run backwards in this capture'); const hist = all.find((r) => r.kind === 'HISTORY'); assert.equal(hist.payload.source, 'KRAKEN_OHLC'); assert.equal(hist.payload.rows.length, 70); assert.ok(hist.payload.rows.every((r) => r.length === 8)); assert.ok(Math.round(Number(hist.payload.rows[69][0]) * 1000) <= hist.payload.receiptTs);
  const cs = all.find((r) => r.kind === 'CASE'); assert.equal(cs.payload.caseId, 'case-i01'); assert.equal(cs.payload.outcome, 'CONSUMED'); assert.equal(cs.payload.provenance, 'LIVE_MODEL'); assert.equal(cs.payload.verificationDigest, digestOf(cs.payload.verification)); assert.equal(cs.payload.verification.verifiedTs, verified.verifiedTs); assert.equal(cs.payload.receiptTs, verified.verifiedTs, 'receipt = when the runtime verified it'); assert.ok(cs.payload.completionTs <= cs.payload.receiptTs);
  assert.ok(!JSON.stringify(cs.payload).includes('ANTHROPIC') && !('apiKey' in cs.payload), 'no provider entitlement material in the bundle'); const ctrl = all.filter((r) => r.kind === 'CONTROL'); assert.deepEqual(ctrl.map((r) => [r.payload.revision, r.payload.cage, r.payload.vetoes]), [[1, false, []], [2, true, ['pred-1']]]);
  const v = verifyBundle(dir, { expectedBinding: { experimentId: 'exp-i01', codeDigest: 'c'.repeat(64) } }); assert.equal(v.ok, true, JSON.stringify(v.reasons)); assert.equal(v.records, all.length); assert.equal(v.clockBackwards, 0); assert.equal(v.capabilities.legacy, false); assert.equal(v.capabilities.evaluations.EXECUTION_SCORING.ok, true); assert.equal(v.capabilities.evaluations.CATALYST_EVIDENCE.ok, true); assert.deepEqual(v.capabilities.evaluations.D2_FLOW_EVENT_RESPONSE, { ok: false, missing: ['WHALE'] }, 'an absent capability is NAMED, never synthesized');
  assert.equal(verifyBundle(dir, { expectedBinding: { experimentId: 'exp-other' } }).reasons[0], 'BINDING_EXPERIMENTID_MISMATCH'); assert.equal(verifyRecording(dir).ok, true, 'the legacy verifier still seals it');
  // the bundle stores: fed in stream order, every source is known-at gated by its own receipt
  const st = createBundleStores(); const noms = []; for (const r of all) { st.apply(r); if (r.kind === 'NOMINATION') noms.push(st.nominations().length); } assert.deepEqual(noms, [1, 2]); assert.equal(st.specs().length, 2); assert.equal(st.fee().feeDigest, m.capabilities.FEE && all.find((r) => r.kind === 'FEE').payload.fee.feeDigest); assert.equal(st.controlRevision(), 2); assert.deepEqual(st.controls(), { kill: false, cage: true, vetoes: ['pred-1'] });
  const consumedAt = (t) => st.caseSource.consumed(coin, { decisionTs: t }); assert.equal(consumedAt(cs.payload.receiptTs - 1), null, 'the case is unknown before its receipt'); const got = consumedAt(cs.payload.receiptTs + 10); assert.equal(got?.ok, true); assert.equal(got.caseId, 'case-i01'); assert.equal(got.analysisId, analysis.analysisId, 'consumed through the production consumer on the carried verification'); assert.equal(st.historyRows().length, c.HISTORY); assert.equal(st.historyRows().length, 0, 'history rows are handed over once');
  // the cold CLI replay (legacy path) still runs the same bundle: typed rows are skipped by the feed replay, the feed rows are replayed exactly
  const specsFile = path.join(TEST_DATA, 'specs-i01.json'); writeFileSync(specsFile, JSON.stringify([SPEC])); const o = []; const code = await runCli(['replay', '--policy', PAPER_POLICY, '--recording', dir, '--pairs', 'XBT/USD', '--specs', specsFile], { env: {}, stdout: (s) => o.push(s), stderr: () => {}, cwd: process.cwd() }); assert.equal(code, 0, o.join('')); const rep = JSON.parse(o.join('')); assert.equal(rep.replayed.messages, m.messages); const vo = []; assert.equal(await runCli(['verify', '--recording', dir], { env: {}, stdout: (s) => vo.push(s), stderr: () => {}, cwd: process.cwd() }), 0); assert.equal(JSON.parse(vo.join('')).checks.recording.bundleVersion, BUNDLE_VERSION);
  // refusals: an interior segment loss, a reordered / duplicated capture sequence, future evidence, a wrong digest, an unknown version
  const clone = (name, mutate) => { const d = path.join(TEST_DATA, name); mkdirSync(d, { recursive: true }); for (const f of readdirSync(dir)) if (statSync(path.join(dir, f)).isFile()) writeFileSync(path.join(d, f), readFileSync(path.join(dir, f))); mutate(d); return d; };
  const seal = (d) => { const mf = JSON.parse(readFileSync(path.join(d, 'manifest.json'), 'utf8')); mf.segments = mf.segments.map((s) => { const buf = readFileSync(path.join(d, s.file)); return { ...s, bytes: buf.length, sha256: createHash('sha256').update(buf).digest('hex') }; }); writeFileSync(path.join(d, 'manifest.json'), JSON.stringify(mf)); };
  const rewrite = (d, fn) => { const f = path.join(d, 'feed-000.jsonl'); const lines = readFileSync(f, 'utf8').split('\n'); writeFileSync(f, fn(lines).join('\n')); seal(d); };
  const swapped = clone('i01-swapped', (d) => rewrite(d, (lines) => { const a = lines[3]; lines[3] = lines[4]; lines[4] = a; return lines; })); assert.equal(verifyBundle(swapped).ok, false); assert.equal(verifyBundle(swapped).reasons[0], 'CAPTURE_ORDER', 'a reordered record is refused even under a fresh seal');
  const dup = clone('i01-dup', (d) => rewrite(d, (lines) => { lines.splice(3, 0, lines[3]); return lines; })); assert.equal(verifyBundle(dup).reasons[0], 'CAPTURE_ORDER', 'a duplicated record is refused');
  const future = clone('i01-future', (d) => rewrite(d, (lines) => lines.map((l) => { if (!l) return l; const r = JSON.parse(l); if (r.kind === 'CASE') { r.payload.completionTs = r.payload.receiptTs + 1; } return JSON.stringify(r); }))); assert.equal(verifyBundle(future).reasons[0], 'RECORD_INVALID'); assert.match(verifyBundle(future).reasons[1], /future knowledge/);
  const tampered = clone('i01-tamper', (d) => { const f = path.join(d, 'feed-000.jsonl'); writeFileSync(f, readFileSync(f, 'utf8').replace('"revision":2', '"revision":3')); }); assert.equal(verifyBundle(tampered).reasons[0], 'SEGMENT_DIGEST', 'a changed control record (same length) breaks the seal');
  const version = clone('i01-version', (d) => { const mf = JSON.parse(readFileSync(path.join(d, 'manifest.json'), 'utf8')); mf.bundleVersion = 'judge-experiment-bundle-0'; writeFileSync(path.join(d, 'manifest.json'), JSON.stringify(mf)); }); assert.ok(verifyBundle(version).reasons.includes('BUNDLE_VERSION_UNKNOWN'));
  const binding = clone('i01-binding', (d) => { const mf = JSON.parse(readFileSync(path.join(d, 'manifest.json'), 'utf8')); mf.binding.policyDigest = 'f'.repeat(64); writeFileSync(path.join(d, 'manifest.json'), JSON.stringify(mf)); }); assert.deepEqual(verifyBundle(binding, { expectedBinding: { policyDigest: m.binding.policyDigest } }).reasons, ['BINDING_POLICYDIGEST_MISMATCH'], 'a changed policy binding is detected');
  // a missing MIDDLE segment: a multi-segment bundle recorded through the recorder with a small segment bound
  const multi = path.join(TEST_DATA, 'i01-multi'); const rec = createFeedRecorder({ dir: multi, clock: () => T0, limits: { maxBytesPerFile: 600, maxFiles: 32 }, validateTyped: (k, p) => recordError(k, p) }); rec.record(null, T0, { connect: true }); for (let i = 0; i < 12; i += 1) { rec.record(bookMsg([[100010 + i, 5]], [[99990 - i, 5]], T0 + i * 1000), T0 + i * 1000); if (i % 4 === 0) rec.record(null, T0 + i * 1000, { kind: 'NOMINATION', payload: { symbol: 'XBT/USD', assetId: 'BTC', source: 'UNIVERSE', nominationKnownAtTs: T0 + i * 1000 } }); } assert.equal(rec.stop(), 'COMPLETE'); const files = readdirSync(multi).filter((f) => f.startsWith('feed-')).sort(); assert.ok(files.length >= 3); assert.equal(verifyBundle(multi).ok, true); unlinkSync(path.join(multi, files[1])); const miss = verifyBundle(multi); assert.equal(miss.ok, false); assert.equal(miss.reasons[0], 'SEGMENT_MISSING', 'an interior loss is never a shorter bundle');
  // generation-time law: the recorder REFUSES an invalid typed row before writing it (and says so), it never writes then hopes
  const gen = createFeedRecorder({ dir: path.join(TEST_DATA, 'i01-gen'), clock: () => T0, validateTyped: (k, p) => recordError(k, p) }); assert.equal(gen.record(null, T0, { kind: 'HISTORY', payload: { symbol: 'XBT/USD', receiptTs: T0, lastCommitted: null, rows: [[(T0 + 60_000) / 1000, '1', '1', '1', '1', '1', '1', 1]], source: 'KRAKEN_OHLC' } }), false); assert.equal(gen.status().state, 'INTERRUPTED'); assert.match(gen.status().reason, /future knowledge/); assert.throws(() => gen.record(null, T0, { kind: 'BOGUS', payload: {} }), (e) => e.code === 'RECORD_KIND');
  assert.equal(recordError('INSTRUMENT', { spec: { ...SPEC, specDigest: 'a'.repeat(64) }, observedTs: T0 }), 'record.INSTRUMENT: specDigest is not the digest of the spec', 'identities are re-derived, never trusted');
});

test('I02. a legacy raw-only COMPLETE recording (no capture sequence, no bundle fields) stays readable and replayable through the legacy path; its capabilities are LIMITED and named — raw-feed COMPLETE is not "inputs exist"; nominations given to the legacy replay survive as the command\'s own inputs, never as bundle records', async () => {
  const dir = path.join(TEST_DATA, 'legacy'); mkdirSync(dir, { recursive: true }); const header = `${JSON.stringify({ header: RECORDING_VERSION, startedTs: T0, segment: 0 })}\n`; const lines = [{ receiptTs: T0, raw: null, connect: true }, ...HANDSHAKE.map((h, i) => ({ receiptTs: T0 + 10 + i, raw: h })), { receiptTs: T0 + 100, raw: bookMsg([[100010.0, 5]], [[99990.0, 5]], T0 + 100, 'snapshot') }]; for (let i = 0; i < 5; i += 1) { lines.push({ receiptTs: T0 + 1000 * (i + 1), raw: bookMsg([[100010.0, 5 - i * 0.5]], [[99990.0, 5]], T0 + 1000 * (i + 1)) }); lines.push({ receiptTs: T0 + 1000 * (i + 1) + 1, raw: tradeMsg(100000 + i, T0 + 1000 * (i + 1), i + 1) }); }
  const body = header + lines.map((l) => JSON.stringify(l)).join('\n') + '\n'; writeFileSync(path.join(dir, 'feed-000.jsonl'), body); const buf = readFileSync(path.join(dir, 'feed-000.jsonl'));
  writeFileSync(path.join(dir, 'manifest.json'), JSON.stringify({ manifestVersion: MANIFEST_VERSION, recordingVersion: RECORDING_VERSION, state: 'COMPLETE', reason: null, startedTs: T0, stoppedTs: T0 + 9000, segments: [{ index: 0, file: 'feed-000.jsonl', bytes: buf.length, messages: lines.length, sha256: createHash('sha256').update(buf).digest('hex'), firstTs: T0, lastTs: lines[lines.length - 1].receiptTs }], messages: lines.length, bytes: buf.length, firstTs: T0, lastTs: lines[lines.length - 1].receiptTs }));
  assert.equal(verifyRecording(dir).ok, true, 'the legacy verifier: COMPLETE'); assert.equal(verifyRecording(dir).bundleVersion, null); const cap = replayCapabilities(dir); assert.equal(cap.legacy, true); assert.equal(cap.present.FEED, lines.length - 1); assert.equal(cap.present.NOMINATION, 0); assert.deepEqual(cap.evaluations.EXECUTION_SCORING, { ok: false, missing: ['INSTRUMENT', 'FEE', 'HISTORY'] }); assert.deepEqual(cap.evaluations.NOMINATION_STREAM, { ok: false, missing: ['NOMINATION'] }); assert.deepEqual(cap.evaluations.CATALYST_EVIDENCE, { ok: false, missing: ['CASE'] });
  const v = verifyBundle(dir); assert.equal(v.ok, true, 'a sealed legacy recording is a valid (limited) bundle'); assert.equal(v.bundleVersion, null); assert.equal(v.records, lines.length); assert.deepEqual([...readBundle(dir)].map((r) => r.seq).slice(0, 3), [1, 2, 3], 'file order is the capture order of a legacy recording');
  const specsFile = path.join(TEST_DATA, 'specs-i02.json'); writeFileSync(specsFile, JSON.stringify([SPEC])); const o = []; assert.equal(await runCli(['replay', '--policy', PAPER_POLICY, '--recording', dir, '--pairs', 'XBT/USD', '--specs', specsFile], { env: {}, stdout: (s) => o.push(s), stderr: () => {}, cwd: process.cwd() }), 0, o.join('')); const rep = JSON.parse(o.join('')); assert.equal(rep.replayed.messages, lines.length); assert.ok(rep.funnel === null || typeof rep.funnel === 'object');
  const st = createBundleStores(); for (const r of readBundle(dir)) st.apply(r); assert.deepEqual(st.nominations(), [], 'a legacy recording carries NO nomination records: the replay command\'s --pairs are its own declared inputs, not recorded discoveries'); assert.equal(st.specs().length, 0); assert.equal(st.fee(), null);
});

test('I03. bounds are explicit: more than 520 nominations flow through the bounded preparation path (slots, never a buy list) and are all captured; the recorder\'s per-kind bound INTERRUPTS the recording with the bound named instead of dropping inputs; the bundle stores refuse beyond their declared bound; the CASE size bound refuses', async () => {
  const fx = catalystPacket(); const coin = fx.coin; const analysis = analysisFor(fx.claim.claimId, 'UPWARD_PRESSURE', fx.packet); const many = []; const extraSpecs = []; for (let i = 0; i < 521; i += 1) { const c = `Q${String(i).padStart(3, '0')}`; extraSpecs.push(specFor(c)); many.push({ symbol: `${c}/USD`, assetId: c, nominationKnownAtTs: fx.packet.asOfTs + 100_000 + i }); }
  const clock = fakeClock(fx.packet.asOfTs + 120_000); const dir = path.join(TEST_DATA, 'bundle-i03'); let controls = { kill: false, cage: false, vetoes: [] };
  const run = await composeJudge({ policyFile: PAPER_POLICY, mode: 'OBSERVE', accountId: 'bundle-many', journal: createMemoryJournal(), clock: pclockOf(clock), specs: [SPEC, ...extraSpecs], controlsSource: () => controls, nominations: () => [{ symbol: 'XBT/USD', assetId: 'BTC', nominationKnownAtTs: clock.now() - 5000 }, ...many], recordDir: dir, writeProjection: false, codeDigest: 'c'.repeat(64), log: () => {} });
  const prep = run.admitNominations(); assert.equal(prep.slots, 6, 'the policy bounds preparation'); assert.equal(run.judge.candidates().length, 6); assert.equal(prep.selected.length, 6); await run.stop();
  const c = kinds(dir); assert.equal(c.NOMINATION, 522, 'every then-known nomination is captured once, bounded by the explicit per-kind bound'); assert.equal(c.INSTRUMENT, 522); assert.equal(verifyBundle(dir).ok, true);
  const st = createBundleStores(); for (const r of readBundle(dir)) st.apply(r); assert.equal(st.nominations().length, 522); const bounded = createBundleStores({ maxNominations: 520 }); assert.throws(() => { for (const r of readBundle(dir)) bounded.apply(r); }, (e) => e.code === 'NOMINATION_BOUND', 'a store bound is an explicit refusal, never a silent cut'); assert.equal(bounded.counts().refusedBound, 1);
  // the recorder bound: NOMINATION limited to 520 -> the 521st INTERRUPTS with the bound named; a composition with an interrupted recorder latches FEED_IMPAIRED
  const lim = createFeedRecorder({ dir: path.join(TEST_DATA, 'i03-limit'), clock: () => T0, limits: { ...RECORDER_DEFAULTS, maxTypedRecords: { ...RECORDER_DEFAULTS.maxTypedRecords, NOMINATION: 520 } }, validateTyped: (k, p) => recordError(k, p) }); let ok = 0; for (const n of many) if (lim.record(null, T0, { kind: 'NOMINATION', payload: { symbol: n.symbol, assetId: n.assetId, source: 'UNIVERSE', nominationKnownAtTs: T0 } })) ok += 1; assert.equal(ok, 520); assert.equal(lim.status().state, 'INTERRUPTED'); assert.match(lim.status().reason, /typed record bound NOMINATION 520/); assert.equal(lim.stop(), 'INTERRUPTED'); assert.equal(verifyBundle(path.join(TEST_DATA, 'i03-limit')).reasons[0], 'RECORDING_INTERRUPTED');
  const big = { assetId: coin, caseId: 'case-big', packetId: fx.packet.packetId, analysisId: analysis.analysisId, completionTs: T0, receiptTs: T0 + 1, direction: 'UPWARD_PRESSURE', provenance: 'LIVE_MODEL', outcome: 'CONSUMED', reasons: [], packet: fx.packet, analysis, verification: { ok: true, manifest: { caseId: 'case-big' }, analyses: [], packets: [], verification: {}, pad: 'x'.repeat(BUNDLE_LIMITS.maxCaseBytes) }, verificationDigest: 'a'.repeat(64) }; assert.match(recordError('CASE', big), /exceeds/);
  assert.deepEqual(Object.keys(CAPABILITY_REQUIREMENTS), ['EXECUTION_SCORING', 'NOMINATION_STREAM', 'CATALYST_EVIDENCE', 'CONTROL_STREAM', 'D2_FLOW_EVENT_RESPONSE', 'D3_RESIDUAL_IGNITION']);
});
